package main

import (
	"regexp/syntax"
	"strings"
	"testing"

	"github.com/dimaggi-ai/tool-guard-core/pkg/domain"
)

// The gitleaks branches of coding_agent_secret_commands.yaml have the form
// and: [<contains guard>, <regex>], generated by scripts/gen-secret-formats.py.
// The engine runs the regex only when a guard literal is present, so a guard
// that a match can lack would hide that match. TestSecretFormatGuards proves
// for each branch that every string the regex matches contains one of the
// guard literals, by walking the regex syntax tree.

// maxFinite bounds the string sets that finiteStrings expands.
const maxFinite = 64

// finiteStrings returns every string re can match when that set is small and
// case-sensitive, for example (?:sk|rk)_ or xox[os]-.
func finiteStrings(re *syntax.Regexp) ([]string, bool) {
	switch re.Op {
	case syntax.OpEmptyMatch, syntax.OpBeginText, syntax.OpEndText,
		syntax.OpBeginLine, syntax.OpEndLine, syntax.OpWordBoundary, syntax.OpNoWordBoundary:
		return []string{""}, true
	case syntax.OpLiteral:
		if re.Flags&syntax.FoldCase != 0 {
			return nil, false
		}
		return []string{string(re.Rune)}, true
	case syntax.OpCharClass:
		var out []string
		for i := 0; i+1 < len(re.Rune); i += 2 {
			for r := re.Rune[i]; r <= re.Rune[i+1]; r++ {
				if len(out) >= 8 {
					return nil, false
				}
				out = append(out, string(r))
			}
		}
		return out, true
	case syntax.OpCapture:
		return finiteStrings(re.Sub[0])
	case syntax.OpAlternate:
		var out []string
		for _, s := range re.Sub {
			f, ok := finiteStrings(s)
			if !ok || len(out)+len(f) > maxFinite {
				return nil, false
			}
			out = append(out, f...)
		}
		return out, true
	case syntax.OpConcat:
		out := []string{""}
		for _, s := range re.Sub {
			f, ok := finiteStrings(s)
			if !ok || len(out)*len(f) > maxFinite {
				return nil, false
			}
			out = product(out, f)
		}
		return out, true
	case syntax.OpQuest:
		f, ok := finiteStrings(re.Sub[0])
		if !ok {
			return nil, false
		}
		return append([]string{""}, f...), true
	}
	return nil, false
}

func product(a, b []string) []string {
	out := make([]string, 0, len(a)*len(b))
	for _, x := range a {
		for _, y := range b {
			out = append(out, x+y)
		}
	}
	return out
}

func allContain(strs, guards []string) bool {
	for _, s := range strs {
		ok := false
		for _, g := range guards {
			if strings.Contains(s, g) {
				ok = true
				break
			}
		}
		if !ok {
			return false
		}
	}
	return true
}

// mustContain reports whether every match of re contains one of the guards.
// It may return false for a regex that does satisfy this; it never returns
// true for one that does not.
func mustContain(re *syntax.Regexp, guards []string) bool {
	keep := 0
	for _, g := range guards {
		if len(g) > keep {
			keep = len(g)
		}
	}
	return len(walk(re, []string{""}, guards, keep-1)) == 0
}

// walk follows re from left to right. pending holds the possible text just
// before re that does not yet contain a guard, cut to its last keep bytes.
// It returns the same set for the text after re; an empty set means every
// path through re has contained a guard. When the text is not known, as
// after a repeat, the set is {""}: this loses matches, so mustContain stays
// sound.
func walk(re *syntax.Regexp, pending, guards []string, keep int) []string {
	if len(pending) == 0 {
		return nil
	}
	if f, ok := finiteStrings(re); ok && len(pending)*len(f) <= 4*maxFinite {
		var out []string
		seen := map[string]bool{}
		for _, s := range product(pending, f) {
			if allContain([]string{s}, guards) {
				continue
			}
			if len(s) > keep {
				s = s[len(s)-keep:]
			}
			if !seen[s] {
				seen[s] = true
				out = append(out, s)
			}
		}
		return out
	}
	switch re.Op {
	case syntax.OpCapture:
		return walk(re.Sub[0], pending, guards, keep)
	case syntax.OpConcat:
		for _, s := range re.Sub {
			pending = walk(s, pending, guards, keep)
			if len(pending) == 0 {
				return nil
			}
		}
		return pending
	case syntax.OpAlternate:
		var out []string
		for _, s := range re.Sub {
			out = append(out, walk(s, pending, guards, keep)...)
		}
		if len(out) > 4*maxFinite {
			return []string{""}
		}
		return out
	case syntax.OpPlus:
		if len(walk(re.Sub[0], pending, guards, keep)) == 0 {
			return nil
		}
	case syntax.OpRepeat:
		if re.Min >= 1 && len(walk(re.Sub[0], pending, guards, keep)) == 0 {
			return nil
		}
	}
	return []string{""}
}

// guardBranches returns each and: [guard, regex] branch under c.
func guardBranches(c domain.Condition, out *[][2]domain.Condition) {
	if len(c.And) == 2 && c.And[1].Operator == domain.OpRegex && isGuard(c.And[0]) {
		*out = append(*out, [2]domain.Condition{c.And[0], c.And[1]})
		return
	}
	for _, s := range append(append([]domain.Condition{}, c.And...), c.Or...) {
		guardBranches(s, out)
	}
	if c.Not != nil {
		guardBranches(*c.Not, out)
	}
}

func isGuard(c domain.Condition) bool {
	if c.Operator == domain.OpContains {
		return true
	}
	if len(c.Or) == 0 {
		return false
	}
	for _, s := range c.Or {
		if s.Operator != domain.OpContains {
			return false
		}
	}
	return true
}

func guardValues(c domain.Condition) []string {
	if c.Operator == domain.OpContains {
		return []string{c.Value.(string)}
	}
	var out []string
	for _, s := range c.Or {
		out = append(out, s.Value.(string))
	}
	return out
}

func TestSecretFormatGuards(t *testing.T) {
	policy := loadSecretCommandsPolicy(t)
	perField := map[string]int{}
	for _, rule := range policy.Rules {
		var branches [][2]domain.Condition
		guardBranches(rule.Conditions, &branches)
		for _, b := range branches {
			guard, rx := b[0], b[1]
			for _, g := range append([]domain.Condition{guard}, guard.Or...) {
				if g.Operator == domain.OpContains && g.Field != rx.Field {
					t.Errorf("%s: guard reads %s, regex reads %s", rule.RuleID, g.Field, rx.Field)
				}
			}
			pattern := rx.Value.(string)
			re, err := syntax.Parse(pattern, syntax.Perl)
			if err != nil {
				t.Errorf("%s: parse %q: %v", rule.RuleID, pattern, err)
				continue
			}
			if !mustContain(re.Simplify(), guardValues(guard)) {
				t.Errorf("%s: a match of %q can lack every guard %q", rule.RuleID, pattern, guardValues(guard))
			}
			perField[rx.Field]++
		}
	}
	// The generator writes the same branch list for every scanned field; the
	// two write rules share the content, new_string and edits lists.
	want := perField["parameters.command"]
	if want == 0 {
		t.Fatal("no guarded gitleaks branches found")
	}
	for _, f := range []string{"parameters.content", "parameters.new_string", "parameters.edits"} {
		if perField[f] != 2*want {
			t.Errorf("field %s has %d branches, want %d", f, perField[f], 2*want)
		}
	}
	t.Logf("guarded gitleaks branches per field: %d", want)
}

// TestMustContain checks the checker on regexes with a known answer.
func TestMustContain(t *testing.T) {
	cases := []struct {
		pattern string
		guards  []string
		want    bool
	}{
		{`glpat-[0-9a-z]{20}`, []string{"glpat-"}, true},
		{`(?:ghu|ghs)_[0-9a-zA-Z]{36}`, []string{"ghu_", "ghs_"}, true},
		{`\b(?:fo1_[\w-]{43}|fm1[ar]_[a-z]{10,}|fm2_[a-z]{10,})`, []string{"fo1_", "fm1", "fm2_"}, true},
		{`xox[os]-\d+`, []string{"xoxo", "xoxs"}, true},
		{`(?:sk|rk)_(?:test|live)_[a-z]{10}`, []string{"sk_test", "sk_live", "rk_test", "rk_live"}, true},
		{`hooks.slack.com/x`, []string{"hooks.slack.com"}, false},      // "." is any character
		{`ab?c`, []string{"abc"}, false},                               // matches "ac"
		{`(?i)glpat-[0-9]{20}`, []string{"glpat-"}, false},             // case-insensitive
		{`xox[pe](?:-[0-9]{10}){3}`, []string{"xoxp-", "xoxe-"}, true}, // the first repeat is required
		{`xox[pe](?:-[0-9]{10}){0,3}`, []string{"xoxp-", "xoxe-"}, false},
		{`a[0-9]*b`, []string{"ab"}, false}, // a repeat splits the guard
		{`(?:foo|bar)baz`, []string{"foo"}, false},
	}
	for _, c := range cases {
		re, err := syntax.Parse(c.pattern, syntax.Perl)
		if err != nil {
			t.Fatalf("parse %q: %v", c.pattern, err)
		}
		if got := mustContain(re.Simplify(), c.guards); got != c.want {
			t.Errorf("mustContain(%q, %q) = %v, want %v", c.pattern, c.guards, got, c.want)
		}
	}
}
